{"path": "/app/bin/crosstabs.py", "content": "#!/usr/bin/env python3
"""Residents survey tables: python3 crosstabs.py INPUT_DIR OUTPUT_FILE (see /app/docs)."""
import csv
import io
import json
import os
import re
import sys
from datetime import datetime, timedelta, timezone
from fractions import Fraction


# ---------------------------------------------------------------- reading

def read_export(path):
    with open(path, "rb") as f:
        raw = f.read()
    text = raw.decode("utf-8-sig")
    first = text.split("\n", 1)[0]
    delim = ","
    for d in (",", ";", "\t"):
        if d in first:
            delim = d
            break
    rows = []
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delim, quotechar='"')
    header = None
    for cells in reader:
        cells = [c.strip() for c in cells]
        if header is None:
            if not any(cells):
                continue
            header = cells
            continue
        if not any(cells):
            continue
        row = {}
        for i, name in enumerate(header):
            if i < len(cells) and cells[i] != "" and name not in row:
                row[name] = cells[i]
        rows.append(row)
    return rows


def parse_offset(s):
    m = re.fullmatch(r"([+-])(\d\d):(\d\d)", s.strip())
    sign = 1 if m.group(1) == "+" else -1
    return sign * timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))


def parse_time(value, meta):
    if value is None:
        return None
    fmt = meta.get("submitted_format", "iso")
    value = value.strip()
    if fmt == "local":
        off = parse_offset(meta["utc_offset"])
        dt = datetime.strptime(value, "%Y-%m-%d %H:%M:%S") if "." not in value else \
            datetime.strptime(value, "%Y-%m-%d %H:%M:%S.%f")
        return dt.replace(tzinfo=timezone(off))
    v = value
    if v.endswith("Z") or v.endswith("z"):
        v = v[:-1] + "+00:00"
    v = v.replace(" ", "T", 1) if "T" not in v else v
    return datetime.fromisoformat(v)


def parse_duration(value, meta):
    if value is None:
        return None
    if meta.get("duration_format") == "clock":
        parts = [int(p) for p in value.split(":")]
        secs = 0
        for p in parts:
            secs = secs * 60 + p
        return Fraction(secs)
    return Fraction(value)


def to_int(value):
    try:
        return int(value)
    except ValueError:
        return int(float(value))


# ---------------------------------------------------------------- answers

class Survey:
    def __init__(self, codebook):
        self.cb = codebook
        self.questions = codebook["questions"]
        self.qmap = {q["id"]: q for q in self.questions}

    @staticmethod
    def options(q):
        return q["bands"] if q["type"] == "age" else q["options"]

    def read_value(self, entry, value):
        rec = entry.get("recode")
        if rec is not None:
            return rec[value]
        return to_int(value)

    def raw_answer(self, q, entry, row, ref_year):
        """Reading rules 4.2-4.6; returns code, frozenset of codes, or None."""
        t = q["type"]
        if t == "single":
            v = row["cells"].get(entry["column"])
            if v is None:
                return None
            code = self.read_value(entry, v)
            return None if self.is_missing(q, code) else code
        if t == "age":
            v = row["cells"].get(entry["column"])
            if v is None:
                return None
            src = entry.get("source")
            if src == "band":
                return self.read_value(entry, v)
            age = to_int(v)
            if src == "birth_year":
                age = ref_year - age
            for b in q["bands"]:
                if b["min"] <= age <= b["max"]:
                    return b["code"]
            return None
        # multi
        chosen = set()
        if "columns" in entry:
            for code, col in entry["columns"].items():
                if row["cells"].get(col) == "1":
                    chosen.add(to_int(code))
        else:
            v = row["cells"].get(entry["column"])
            if v is not None:
                for el in v.split(entry["separator"]):
                    el = el.strip()
                    if el == "":
                        continue
                    chosen.add(self.read_value(entry, el))
        if not chosen:
            return None
        excl = {o["code"] for o in q["options"] if o.get("exclusive")}
        non_excl = {c for c in chosen if c not in excl}
        if non_excl:
            chosen = non_excl
        elif len(chosen) >= 2:
            return None
        miss = {o["code"] for o in q["options"] if o.get("missing")}
        chosen = {c for c in chosen if c not in miss}
        return frozenset(chosen) if chosen else None

    def is_missing(self, q, code):
        return any(o["code"] == code and o.get("missing") for o in q.get("options", []))

    def answers(self, row):
        """Valid answers of one kept row: dict question id -> code / frozenset (asked and valid only)."""
        ver = row["version"]
        ref_year = int(str(self.cb["reference_date"])[:4])
        out = {}
        asked = {}

        def is_asked(qid):
            if qid in asked:
                return asked[qid]
            asked[qid] = False  # guards against cycles
            q = self.qmap.get(qid)
            res = False
            if q is not None:
                entry = q["versions"].get(ver)
                if entry is not None:
                    ok = row["complete"] or entry["page"] <= row["last_page"]
                    if ok and q.get("ask_if"):
                        ai = q["ask_if"]
                        res = False
                        if is_asked(ai["question"]):
                            a = valid(ai["question"])
                            if a is not None:
                                codes = set(ai["codes"])
                                if isinstance(a, frozenset):
                                    res = bool(a & codes)
                                else:
                                    res = a in codes
                    else:
                        res = ok
            asked[qid] = res
            return res

        def valid(qid):
            if qid in out:
                return out[qid]
            q = self.qmap[qid]
            a = None
            if is_asked(qid):
                a = self.raw_answer(q, q["versions"][ver], row, ref_year)
            out[qid] = a
            return a

        for q in self.questions:
            valid(q["id"])
        return {k: v for k, v in out.items() if v is not None}


# ---------------------------------------------------------------- main steps

def median(vals):
    vals = sorted(vals)
    n = len(vals)
    if n % 2:
        return Fraction(vals[n // 2])
    return (vals[n // 2 - 1] + vals[n // 2]) / 2


def load_rows(indir, codebook):
    versions = codebook["versions"]
    exp = os.path.join(indir, "exports")
    names = sorted(n for n in os.listdir(exp)
                   if n.endswith(".csv") and os.path.isfile(os.path.join(exp, n)))
    rows = []
    for n in names:
        for cells in read_export(os.path.join(exp, n)):
            ver = cells.get("form_version")
            meta = versions[ver]["meta"]
            status = cells.get(meta["status"])
            lp = cells.get(meta["last_page"])
            rows.append({
                "version": ver,
                "cells": cells,
                "id": cells.get(meta["id"]),
                "complete": status == meta["complete"],
                "time": parse_time(cells.get(meta["submitted"]), meta),
                "duration": parse_duration(cells.get(meta["duration"]), meta),
                "last_page": to_int(lp) if lp is not None else 0,
            })
    return rows


def rake(resp_answers, survey, wcfg):
    n = len(resp_answers)
    w = [1.0] * n
    dims = []
    for d in wcfg.get("dimensions", []):
        qid = d["question"]
        cats = {}
        for code_text, t in d["targets"].items():
            cats[to_int(code_text)] = float(t)
        present = set()
        for a in resp_answers:
            v = a.get(qid)
            if v is not None and not isinstance(v, frozenset):
                present.add(v)
        cats = {c: t for c, t in cats.items() if c in present}
        total = sum(cats.values())
        if not cats or total <= 0:
            dims.append(None)
            continue
        share = {c: t / total for c, t in cats.items()}
        member = [a.get(qid) if a.get(qid) in share else None for a in resp_answers]
        dims.append((share, member))
    tol = wcfg.get("tolerance", 1e-10)
    for _ in range(int(wcfg.get("max_iterations", 100))):
        done = True
        for dim in dims:
            if dim is None:
                continue
            share, member = dim
            tot = 0.0
            wc = {c: 0.0 for c in share}
            for i, c in enumerate(member):
                if c is not None:
                    tot += w[i]
                    wc[c] += w[i]
            f = {}
            for c in share:
                f[c] = share[c] * tot / wc[c] if wc[c] > 0 else 1.0
                if abs(f[c] - 1) > tol:
                    done = False
            for i, c in enumerate(member):
                if c is not None:
                    w[i] *= f[c]
        if done:
            break
    m = sum(w) / n
    hi, lo = wcfg["cap"] * m, wcfg["floor"] * m
    w = [min(max(x, lo), hi) for x in w]
    s = sum(w)
    k = n / s
    return [x * k for x in w]


def r2(x):
    return round(x + 0.0, 2) + 0.0


def build(indir):
    def jload(name):
        with open(os.path.join(indir, name), encoding="utf-8-sig") as f:
            return json.load(f)

    codebook = jload("codebook.json")
    wcfg = jload("weighting.json")
    plan = jload("tables.json")
    survey = Survey(codebook)
    vkeys = list(codebook["versions"].keys())
    stats = {v: {"version": v, "rows": 0, "duplicates": 0, "short_partials": 0,
                 "speeders": 0, "complete": 0, "partial": 0} for v in vkeys}

    rows = load_rows(indir, codebook)
    for r in rows:
        stats[r["version"]]["rows"] += 1

    # 1. one row per respondent
    best = {}
    order = []
    for r in rows:
        k = r["id"]
        if k not in best:
            best[k] = r
            order.append(k)
            continue
        cur = best[k]
        if (r["complete"], r["time"]) > (cur["complete"], cur["time"]):
            drop, best[k] = cur, r
        else:
            drop = r
        stats[drop["version"]]["duplicates"] += 1
    kept = [best[k] for k in order]

    # 2. short partials
    pmin = codebook["partial_min_page"]
    tmp = []
    for r in kept:
        if not r["complete"] and r["last_page"] < pmin:
            stats[r["version"]]["short_partials"] += 1
        else:
            tmp.append(r)
    kept = tmp

    # 3. speeders
    med = {}
    for v in vkeys:
        ds = [r["duration"] for r in kept if r["version"] == v and r["complete"]]
        if ds:
            med[v] = median(ds)
    tmp = []
    for r in kept:
        if r["complete"] and r["duration"] * 5 < med[r["version"]] * 2:
            stats[r["version"]]["speeders"] += 1
        else:
            tmp.append(r)
    kept = tmp
    for r in kept:
        stats[r["version"]]["complete" if r["complete"] else "partial"] += 1

    ans = [survey.answers(r) for r in kept]
    n = len(kept)
    summary = {"versions": [stats[v] for v in vkeys], "respondents": n,
               "effective_n": None, "weight_min": None, "weight_max": None}
    w = []
    if n:
        w = rake(ans, survey, wcfg)
        sw = sum(w)
        summary["effective_n"] = r2(sw * sw / sum(x * x for x in w))
        summary["weight_min"] = r2(min(w))
        summary["weight_max"] = r2(max(w))

    # tables
    columns = [("total", None, None)]
    for qid in plan.get("banner", []):
        q = survey.qmap[qid]
        for o in Survey.options(q):
            if not o.get("missing"):
                columns.append((f"{qid}:{o['code']}", qid, o["code"]))

    tables = []
    for t in plan.get("tables", []):
        q = survey.qmap[t["question"]]
        qid = q["id"]
        opts = [o for o in Survey.options(q) if not o.get("missing")]
        nets = t.get("nets", [])
        cols = []
        for cid, bq, bcode in columns:
            idx = [i for i in range(n)
                   if ans[i].get(qid) is not None
                   and (bq is None or ans[i].get(bq) == bcode)]
            wb = sum(w[i] for i in idx)
            values = {}
            rows_def = [(str(o["code"]), {o["code"]}) for o in opts] + \
                       [(net["id"], set(net["codes"])) for net in nets]

            def hit(i, codes):
                a = ans[i][qid]
                return bool(a & codes) if isinstance(a, frozenset) else a in codes

            for key, codes in rows_def:
                if not idx or wb == 0:
                    values[key] = None
                else:
                    values[key] = r2(100 * sum(w[i] for i in idx if hit(i, codes)) / wb)
            if t.get("mean"):
                score = {o["code"]: o["score"] for o in opts}
                if not idx or wb == 0:
                    values["mean"] = None
                else:
                    values["mean"] = r2(sum(w[i] * score[ans[i][qid]] for i in idx) / wb)
            cols.append({"column": cid, "base": len(idx),
                         "weighted_base": r2(wb) if idx else 0, "values": values})
        tables.append({"table": t["id"], "columns": cols})

    return {"survey": codebook["survey"], "summary": summary, "tables": tables}


def main():
    if len(sys.argv) != 3:
        sys.stderr.write("usage: crosstabs.py INPUT_DIR OUTPUT_FILE\n")
        return 2
    result = build(sys.argv[1])
    with open(sys.argv[2], "w", encoding="utf-8") as f:
        json.dump(result, f, indent=1)
        f.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
